"""Probe a directory of *.json files and summarize their cost_usd values.

Last verified: 2026-08-23
"""

import json
import os
import sys
import tempfile
from typing import Any


def collect_costs(directory: str) -> "tuple[list[float], list[str]]":
    costs: list[float] = []
    errors: list[str] = []
    for name in sorted(os.listdir(directory)):
        if not name.endswith(".json"):
            continue
        path = os.path.join(directory, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError):
            errors.append(name)
            continue
        if not isinstance(data, dict):
            errors.append(name)
            continue
        if "cost_usd" in data:
            value = data["cost_usd"]
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                costs.append(float(value))
            else:
                errors.append(name)
    return costs, errors


def build_summary(costs: "list[float]", errors: "list[str]") -> "dict[str, Any]":
    total = sum(costs)
    mean = total / len(costs) if costs else 0.0
    return {"total": total, "mean": mean, "errors": errors}


def write_summary_atomically(summary: "dict[str, Any]", destination: str) -> None:
    directory = os.path.dirname(os.path.abspath(destination)) or "."
    fd, tmp_path = tempfile.mkstemp(prefix=".summary_", suffix=".tmp", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(summary, handle)
        os.replace(tmp_path, destination)
    except BaseException:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        return 2

    target_dir = sys.argv[1]
    if not os.path.isdir(target_dir):
        print(f"error: no such directory: {target_dir}", file=sys.stderr)
        return 1

    destination = os.path.join(os.getcwd(), "summary.json")
    if os.path.exists(destination):
        print(f"error: refusing to overwrite existing {destination}", file=sys.stderr)
        return 1

    costs, errors = collect_costs(target_dir)
    summary = build_summary(costs, errors)
    write_summary_atomically(summary, destination)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
